---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Response versions: Regenerate an answer and flip between versions.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change response-versions.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './response-versions.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="response-versions" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="rvx mx-grow">
  <div class="bub">Write a headline for the pricing page</div>
  <div class="rvx-a">
    <p class="msg rvx-t"></p>
    <div class="rvx-bar mx-ic">
      <div class="rvx-pg"><button class="ib rvx-prev mx-press" aria-label="Previous version" data-tip="Previous"><svg class="i s"><use href="#i-chev-l"/></svg></button><span class="rvx-n num">1 / 1</span><button class="ib rvx-next mx-press" aria-label="Next version" data-tip="Next"><svg class="i s"><use href="#i-chev-r"/></svg></button></div>
      <button class="ib rvx-re mx-press" aria-label="Regenerate" data-tip="Regenerate" data-tip-k="⌘R"><svg class="i s"><use href="#i-refresh"/></svg></button>
      <button class="ib rvx-cp mx-press" aria-label="Copy" data-tip="Copy"><svg class="i s"><use href="#i-copy"/></svg></button>
      <span class="rvx-st muted"></span>
    </div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './response-versions.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Response versions ---------- */
.rvx{display:flex;flex-direction:column;gap:14px}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on its buttons shows at once (.mx-press); Copy's icon and its
   tick crossfade (.mx-ic); the answer eases to its new height on the spring (.mx-grow) */
.rvx-a{display:flex;flex-direction:column;gap:var(--dm-s-2)}
/* the answer is as tall as its words in every style (owner's notes, 18 Nov): the component grows with them (grow()), and a
   version streaming in keeps the height of the one it replaces, then eases to its own. The bar's first button reaches 6px
   past the column, so the growing box lets that much show, focus ring included */
.rvx.growing{overflow-clip-margin:12px}
/* nothing in the bar shrinks on a click (owner, 18 Nov) */
.rvx-bar .ib:active{transform:none}
:root[data-style="clean"] .rvx-bar .ib:active,:root [data-style="clean"] .rvx-bar .ib:active,:root [data-style="clean"].rvx-bar .ib:active{transform:none}
.rvx-t .w{animation:rvw .45s var(--dm-ease) both}
@keyframes rvw{from{opacity:0;filter:blur(4px)}to{opacity:1;filter:none}}
.rvx-t.out{animation:rvo .3s var(--dm-ease) both}
@keyframes rvo{to{opacity:0;filter:blur(4px);transform:translateY(-2px)}}
.rvx-bar{display:flex;align-items:center;gap:2px;margin-left:-6px}
/* its icon buttons, the pager's included, are the library's 28px icon buttons */
.rvx-bar .ib{width:28px;height:28px}
.rvx-pg{display:flex;align-items:center;gap:0}
.rvx-pg .ib[disabled]{opacity:1;cursor:not-allowed;background:none;color:var(--dm-dis)}
/* the bar sits on the stage, where --dm-row is the stage's own colour: it sets --dm-row to a quiet 5% of the text colour, as the
   other cards on the stage do, so its buttons keep the one shared hover */
.rvx-bar{--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
.rvx-n{font-size:12px;color:var(--dm-muted);min-width:34px;text-align:center}
.rvx-re svg{transition:transform .7s var(--dm-ease)}
.rvx-re.go svg{transform:rotate(360deg)}
.rvx-st{font-size:12px;margin-left:6px}
/* Clean (owner, 18 Nov): words fade in and out without a blur */
@keyframes rvwc{from{opacity:0}to{opacity:1}}
@keyframes rvoc{to{opacity:0;transform:translateY(-2px)}}
:root[data-style="clean"] .rvx-t .w,:root [data-style="clean"] .rvx-t .w,:root [data-style="clean"].rvx-t .w{animation-name:rvwc;animation-duration:var(--dm-t-slow)}
:root[data-style="clean"] .rvx-t.out,:root [data-style="clean"] .rvx-t.out,:root [data-style="clean"].rvx-t.out{animation-name:rvoc;animation-duration:var(--dm-t)}
/* Clean (owner, 22 Nov: "differentiate Clean from Soft"): the answer is a version card. The answer comes first, 16px in
   from the card's edges; under it a hairline, and under that the bar as a plain row with no strip (owner, 23 Nov: "just add
   a divider line"): the arrows and the count on the left with what is happening beside them, Regenerate and Copy at the
   right. Its buttons are 28px, 16px from the hairline, the card's bottom edge and its sides. Soft and Blueprint keep the
   answer flat in the thread with its bar under it, in the same order */
:root[data-style="clean"] .rvx-a,:root [data-style="clean"] .rvx-a,:root [data-style="clean"].rvx-a{gap:0;background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);overflow:hidden}
:root[data-style="clean"] .rvx-bar,:root [data-style="clean"] .rvx-bar,:root [data-style="clean"].rvx-bar{margin:0;padding:16px;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .rvx-t,:root [data-style="clean"] .rvx-t,:root [data-style="clean"].rvx-t{padding:16px}
:root[data-style="clean"] .rvx-st,:root [data-style="clean"] .rvx-st,:root [data-style="clean"].rvx-st{order:1;margin-left:var(--dm-s-2);min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
:root[data-style="clean"] .rvx-re,:root [data-style="clean"] .rvx-re,:root [data-style="clean"].rvx-re{order:2;margin-left:auto}
:root[data-style="clean"] .rvx-cp,:root [data-style="clean"] .rvx-cp,:root [data-style="clean"].rvx-cp{order:3}
.rvx-cp.copied,.aab-cp.copied{color:var(--dm-ok-mark)!important}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, DM, I, REDUCE, copied, grow, swap } from '../core/core.js';
DM.def('response-versions', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{l}', I('chev-l')).replace('{rr}', I('chev-r')).replace('{re}', I('refresh')).replace('{cp}', I('copy'));
  const pool = [
    'Pricing that grows with your team. Start free, upgrade when the work gets serious.',
    'One plan per stage of your team. No seat math, no surprises on the invoice.',
    'Design faster with an agent on every plan. Pay for what you ship, not for seats.',
    'Simple pricing for teams who ship. Free to start, fair as you grow.'
  ];
  const vers = [pool[0]]; let cur = 0, busy = false;
  const t = $('.rvx-t', r), n = $('.rvx-n', r), pv = $('.rvx-prev', r), nx = $('.rvx-next', r), re = $('.rvx-re', r), st = $('.rvx-st', r);
  const nav = () => { n.textContent = (cur + 1) + ' / ' + vers.length; pv.disabled = cur === 0 || busy; nx.disabled = cur === vers.length - 1 || busy; };
  // no room kept for a longer answer, in every style (owner, 18 Nov). The component grows with its words (grow(), once its
  // entrance has settled), and a version streaming in keeps the height of the one it replaces, then eases to its own
  const rvx = $('.rvx', r);
  const growing = Promise.resolve().then(() => Promise.all(rvx.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && rvx.isConnected) c.offs.push(grow(rvx)); });
  const keep = () => { if (t.textContent.trim()) t.style.minHeight = t.offsetHeight + 'px'; };
  const fit = () => { if (!t.style.minHeight) return; const was = t.offsetHeight; t.style.minHeight = ''; const h = t.offsetHeight; if (h >= was || REDUCE) return;
    t.style.minHeight = was + 'px'; void t.offsetHeight; t.style.transition = 'min-height var(--dm-t) var(--dm-ease)'; t.style.minHeight = h + 'px';
    c.later(460, () => { t.style.transition = ''; t.style.minHeight = ''; }); };
  async function stream(s){
    keep(); t.classList.add('out'); await c.wait(260); t.classList.remove('out'); t.innerHTML = '';
    for (const w of s.split(' ')){ t.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await c.wait(45); }
    fit();
  }
  async function show(i){ cur = i; nav(); t.classList.add('out'); await c.wait(240); t.classList.remove('out'); t.innerHTML = vers[i].split(' ').map((w, k) => `<span class="w" style="animation-delay:${k * 12}ms">${w} </span>`).join(''); }
  pv.onclick = () => c.run(() => show(cur - 1));
  nx.onclick = () => c.run(() => show(cur + 1));
  re.onclick = () => { if (busy) return; busy = true; re.classList.add('go'); c.later(700, () => re.classList.remove('go'));
    c.run(async () => { swap(st, 'Writing a new version'); st.classList.add('shim');
      const s = pool[vers.length % pool.length]; vers.push(s); cur = vers.length - 1; nav();
      await stream(s); busy = false; nav(); st.classList.remove('shim'); swap(st, ''); }); };
  const cp = $('.rvx-cp', r);
  cp.onclick = () => copied(cp, vers[cur]);
  // (the first version starts once grow() has the component, so its first lines ease it open rather than jump it, motion pieces)
  c.run(async () => { busy = true; nav(); await c.wait(300); await growing; await stream(vers[0]); busy = false; nav();
    // then one regenerate plays by itself, so the version count and arrows show what they do, unless you have taken over
    await c.step(1900); if (vers.length === 1) re.click(); });
});
